'use strict';
(()=>{
const C=window.MISSION,CFG=window.MISSION_CONFIG||{},KEY='ludaria_'+C.slug+'_v1',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s),blank=()=>({version:1,page:0,fields:{},checks:{},visited:[],open:false});let s=blank(),storage=true,lastFocus;
try{const x=JSON.parse(localStorage.getItem(KEY));if(x?.version===1)s={...blank(),...x};}catch(_){storage=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch(_){storage=false;$('#store').textContent='Guardado no disponible: conserva una copia del registro.'}}
const field=id=>s.fields[id]??'';
function fields(){document.querySelectorAll('[data-field]').forEach(x=>{if(x.type==='checkbox')x.checked=!!field(x.dataset.field);else x.value=field(x.dataset.field)});document.querySelectorAll('[data-check]').forEach(x=>x.checked=!!s.checks[x.dataset.check]);}
function render(){s.page=Math.min(C.pages.length-1,Math.max(0,s.page));s.visited=[...new Set([...s.visited,s.page])];save();const p=C.pages[s.page];document.body.classList.toggle('is-cover',s.page===0);$('#stage').innerHTML=s.page===0?`<section class="cover-content"><span class="eyebrow">${C.type} · ${C.place}</span><h1>${C.title}</h1><p class="lead">${p.intro}</p><div class="cover-meta">90 min sincrónicos · ${C.autonomous?C.autonomous+' min autónomos previos':'sin carga autónoma adicional'}</div>${C.mentor?`<p class="mentor">${C.mentor} acompaña este tramo.<small>${C.attribute}</small></p>`:''}<div class="actions"><button class="button" data-go="1">Comenzar el recorrido</button><button class="button secondary" data-action="guide">Guía docente</button></div><p class="note">El facilitador conduce la sesión en vivo. Cada participante avanza en su dispositivo.</p></section>`:`<section class="scene-content wide"><div class="section-title"><div><span class="eyebrow">${C.place} · ${s.page+1} / ${C.pages.length}</span><h2>${p.title}</h2><p class="lead">${p.intro}</p></div><span class="time-label">${p.time} min</span></div><div class="lesson-content">${p.html}</div><p class="product"><strong>Producto:</strong> ${p.product}</p></section>`;
fields();$('#previous').disabled=s.page===0;$('#next').disabled=s.page===C.pages.length-1;$('#select-page').value=s.page;$('#page-count').textContent=`${s.page+1} / ${C.pages.length}`;$('#route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot${s.page===i?' current':''}${s.visited.includes(i)?' visited':''}" data-go="${i}" aria-label="${esc(p.title)}" aria-current="${s.page===i?'page':'false'}"></button>`).join('');$('#stage').focus({preventScroll:true});window.scrollTo(0,0);history.replaceState(null,'','#pantalla-'+(s.page+1));if(s.open&&$('#orbe'))$('#orbe').classList.add('restored');document.querySelectorAll('[data-quiz]').forEach(q=>{if(s.checks[q.dataset.quiz])feedback(q)});
}
function record(){const a=[C.title,'LUDARIA · REGISTRO LOCAL','Fecha de exportación: '+new Date().toISOString(),''];for(const [id,label] of Object.entries(C.labels))a.push(label+': '+(typeof field(id)==='boolean'?(field(id)?'Seleccionado':'No seleccionado'):field(id)||'—'));a.push('','Las respuestas abiertas requieren revisión humana. Este archivo no acredita envío ni evaluación externa.');return a.join('\n\n')}
function show(title,html){lastFocus=document.activeElement;$('#modal-body').innerHTML=`<h2 id="modal-title">${title}</h2>${html}`;$('#modal').showModal()}
function notify(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(notify.t);notify.t=setTimeout(()=>$('#toast').hidden=true,3000)}
function notebook(){show('Registro del buscador',`<p>Datos de este navegador. Descarga o copia el registro y compártelo por el canal real indicado.</p><label class="field">Registro completo<textarea id="record" readonly>${esc(record())}</textarea></label><div class="actions"><button class="button" data-action="download">Descargar TXT</button><button class="button secondary" data-action="copy">Copiar</button><button class="text-button" data-action="reset">Borrar borrador local…</button></div>`)}
function feedback(q){const id=q.dataset.quiz,v=field(id),out=q.querySelector('.quiz-feedback');if(!v){out.textContent='Elige una opción para contrastar tu decisión.';return}const good=v===q.dataset.answer;out.textContent=(good?'Coincide con la pauta propuesta. ':'Revisa esta distinción. ')+q.dataset.explanation;out.hidden=false;if(good&&q.dataset.unlock)q.querySelector('.extra').hidden=false;s.checks[id]=true;save()}
function download(){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([record()],{type:'text/plain;charset=utf-8'}));a.href=u;a.download=C.slug+'-registro.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);notify('Descarga solicitada. Si el marco la restringe, copia el registro.')}
document.addEventListener('input',e=>{const x=e.target;if(x.matches('[data-field]')){s.fields[x.dataset.field]=x.type==='checkbox'?x.checked:x.value;save()}});
document.addEventListener('change',e=>{if(e.target.id==='select-page'){s.page=Number(e.target.value);render()}if(e.target.matches('[data-check]')){s.checks[e.target.dataset.check]=e.target.checked;save()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(b.dataset.go!==undefined){s.page=Number(b.dataset.go);if($('#modal').open)$('#modal').close();render()}else if(a==='close')$('#modal').close();else if(a==='guide')show('Guía docente',`<p>${C.guide}</p><div class="modal-grid">${C.pages.map((p,i)=>`<article class="panel"><strong>${i+1} · ${p.title} · ${p.time} min</strong><p>${p.prompt||p.intro}</p><p>Producto: ${p.product}</p></article>`).join('')}</div><p>Progreso de recorrido y respuestas locales no equivalen a calificación.</p>`);else if(a==='sources')show('Fuentes y alcance',C.sources.map(x=>`<article class="panel"><h3>${x.title}</h3><p>${x.apa}</p>${x.url?`<p><a href="${x.url}" target="_blank" rel="noopener">Consultar fuente</a></p>`:''}<p>${x.limit}</p></article>`).join(''));else if(a==='notebook')notebook();else if(a==='download')download();else if(a==='copy'){try{await navigator.clipboard.writeText(record());notify('Registro copiado.')}catch(_){notebook();$('#record').select();notify('Selecciona y copia el registro.')}}else if(a==='check')feedback(b.closest('[data-quiz]'));else if(a==='hint'){b.closest('[data-quiz]').querySelector('.hint').hidden=false;}else if(a==='assist'){const q=b.closest('[data-quiz]');q.querySelector('.extra').hidden=false;q.querySelector('.quiz-feedback').textContent='Apertura acompañada: revisen juntos la pauta. No se otorgan puntos.';q.querySelector('.quiz-feedback').hidden=false;}else if(a==='resources'){show('Recursos externos y alternativa local',Object.entries(CFG).map(([k,v])=>`<article class="panel"><h3>${C.resources[k]||k}</h3>${/^https:\/\//.test(v)?`<a href="${esc(v)}" target="_blank" rel="noopener">Abrir recurso configurado</a>`:'<p>Enlace por configurar. Usa los campos locales y comparte el archivo por el canal que indique el facilitador.</p>'}</article>`).join(''));}else if(a==='orbe'){s.open=true;save();$('#orbe').classList.add('restored');$('#ceremony-message').hidden=false;notify('Orbe restaurado en la ceremonia local.')}else if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(_){notify('Pantalla completa no disponible en este marco.')}}else if(a==='reset')show('Borrar borrador local','<p>Descarga antes de borrar si quieres conservar tus respuestas.</p><div class="actions"><button class="button" data-action="reset-confirm">Borrar solo esta misión</button><button class="button secondary" data-action="close">Cancelar</button></div>');else if(a==='reset-confirm'){try{localStorage.removeItem(KEY)}catch(_){}s=blank();$('#modal').close();render();}});
$('#previous').onclick=()=>{s.page--;render()};$('#next').onclick=()=>{s.page++;render()};$('#modal').addEventListener('close',()=>lastFocus?.focus());document.addEventListener('keydown',e=>{if($('#modal').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='ArrowRight'&&s.page<C.pages.length-1){s.page++;render()}if(e.key==='ArrowLeft'&&s.page>0){s.page--;render()}});
$('#select-page').innerHTML=C.pages.map((p,i)=>`<option value="${i}">${i+1} · ${esc(p.title)}</option>`).join('');const h=location.hash.match(/pantalla-(\d+)/);if(h)s.page=Number(h[1])-1;render();if(!storage)$('#store').textContent='Guardado no disponible: exporta tu registro.';
})();
